  },
  AvgDialog_131226_Content_38 = {
    Text = "그래도 그 물건이 여러분에게 소중해 보여서, 막 이곳에 왔는데 잃어버리면 어디서 찾아야 할지도 모를 것 같아 가져다줬을 뿐일세."
  },
  AvgDialog_131226_Content_39 = {
    Text = "정말 감사합니다..."
