  AvgDialog_52001_Content_74 = {
    Text = "그녀를 사라라고 불러줘. 데보라는 입술을 달싹였지만, 이미 아무런 소리도 낼 수 없었다."
  },
  AvgDialog_52001_Content_75 = {
