  AvgDialog_71990_Content_32 = {
    Text = "사라의 병상에 가까이 다가간다. 메이슨이 그녀를 일으켜 앉힌다. 사라는 숨을 헐떡이며 몸을 가누려 애쓰고, 마침내 억지 미소를 지으며 당신을 올려다본다."
  },
  AvgDialog_71990_Content_33 = {
    Text = "친절한 {Male=분이시군요,Female=분이시군요}... 부탁 하나만 들어주시겠어요?"
