  AvgDialog_71990_Content_41 = {
    Text = "걱정 마세요, 쉽게 포기하지 않을 거예요. 그날이 올 때까지 살아남기 위해 발버둥 칠 거예요. 단 하나의 희망이라도 있다면... 아이들을 한 번 더 보고 싶어요."
  },
  AvgDialog_71990_Content_42 = {
    Text = "황량한 런던 거리에서, 긴 한숨을 내쉰다. 먼지투성이 길조차 그 방의 무거운 공기보다는 상쾌하다."
  },
  AvgDialog_71990_Content_43 = {
    Text = "융해·돌이 당신 옆에서 반 발짝 거리를 유지하며 걷는다."
