  AvgDialog_71993_Content_8 = {
    Text = "검은 방패를 든 작은 소년이 당신에게 다가온다."
  },
  AvgDialog_71993_Content_9 = {
    Text = "당신들은... 살아남은 생존자들인가요? 어서, 절 따라 안으로!"
  },
  AvgDialog_71994_Content_1 = {
    Text = "의식 공간이 완전히 붕괴한다. 환상의 먼지가 부드럽게 떨어지며, 당신 앞에 원래의 연구실타래이 모습을 드러낸다."
  },
  AvgDialog_71994_Content_2 = {
    Text = "왜 끝을 받아들이지 않지? 차원의 틈에 묻히면, 다시는 그분의 시선을 견딜 필요가 없을 텐데."
  },
  AvgDialog_71994_Content_3 = {
    Text = "얼마나 지고한 영광인가! 얼마나 초월적인 선물인가!"
  },
  AvgDialog_71994_Content_4 = {
    Text = "안타까워, 너무 안타까워. 이제 내 손으로 직접... 이 이미 죽은 도시를..."
