  AvgDialog_71995_Content_1 = {
    Text = "혼돈의 공간이 뒤틀린 윤곽과 함께 순식간에 연구실타래 전체를 삼킨다."
  },
  AvgDialog_71995_Content_2 = {
    Text = "혼돈의 환상이 당신 앞에 펼쳐지고, 어둡고 알아볼 수 없는 짐승 무리가 당신 둘을 둘러싼다."
  },
  AvgDialog_71995_Content_3 = {
    Text = "나의 실타래험장, 나의 도살장에 온 걸 환영해."
  },
  AvgDialog_71995_Content_4 = {
    Text = "가라, 귀여운 아이들아. 이 무지한 바보들에게 교훈을 줘."
  },
  AvgDialog_71996_Content_10 = {
    Text = "물론 내 연구실타래이지."
  },
  AvgDialog_71996_Content_11 = {
    Text = "기억나? 내가 「지름길」을 이용할 수 있다고 말했잖아."
