  AvgDialog_71998_Content_2 = {
    Text = "연구실타래이 거대한 진동으로 흔들린다. 테이블에서 플라스크와 시험관이 굴러떨어지고, 바닥에서는 기괴한 연기가 피어오른다."
  },
  AvgDialog_71998_Content_3 = {
    Text = "실타래험대와 시약 선반이 차례로 무너진다. 벽에 걸린 시계와 장식물조차 떨어질 위기에 처해 있다."
