  },
  AvgDialog_71998_Content_6 = {
    Text = "우리 같이 묻히게 생겼네, 미사그의 강아지. 기뻐? 꼬리라도 흔들어 봐. 이건 네게 주어진 드문 영광이니까."
  },
  AvgDialog_71998_Content_7 = {
    Text = "대답하기도 전에, 시야가 어둠에 휩싸인다."
