  AvgDialog_72003_Content_6 = {
    Text = "시계탑에 그들을 끌어당기는 무언가가 있어."
  },
  AvgDialog_72003_Content_7 = {
    Text = "지하실타래 복도 입구에 서성이던 융식 변이체들을 떠올린다. 그들 또한 무언가를 갈망하며 그곳에 모여 있었다."
  },
  AvgDialog_72003_Content_8 = {Text = "..."},
  AvgDialog_72003_Content_9 = {
    Text = "오늘 시계탑에 온 사람은..."
