  AvgDialog_72005_Content_2 = {
    Text = "응, 저 괴물들은 그 대재앙 이후에 나타났어."
  },
  AvgDialog_72005_Content_20 = {
    Text = "그랬군. 저 변이체들이 들었던 걸 너도 들었나 보네."
  },
  AvgDialog_72005_Content_21 = {
    Text = "돌의 목소리는 여전히 기계적이고 차가웠다. 그에 비하면 저 기괴한 울음은 고통의 온기라도 발산하고 있다."
  },
  AvgDialog_72005_Content_22 = {
    Text = "마음을 가라앉히고 그 목소리들을 포착해 봐. 은심 안의 영적 에너지가 너무 미약해서 기기로는 감지할 수 없어. 이건 너만이 할 수 있는 일이야."
  },
  AvgDialog_72005_Content_23 = {
    Text = "멀고 알 수 없는 곳에서 희미한 북 소리가 들린다. 어둠 속에 숨겨진 비밀의 길이 나타난다."
  },
  AvgDialog_72005_Content_24 = {
