  AvgDialog_72009_Content_65 = {
    Text = "돌이 그랬어, 네 의식은 온 세상을 담고 있다고. 기억해 내기만 하면, 은빛 열쇠가 기억의 힘을 활성화시킬 수 있을 거야!"
  },
  AvgDialog_72009_Content_66 = {
    Text = "부드러운 백색 빛이 점차 시야를 감싸고, 익숙한 네 개의 실타래루엣이 환영처럼 눈앞에 나타난다."
  },
  AvgDialog_72009_Content_67 = {
    Text = "수호자! 정말 너야?"
