  AvgDialog_72010_Content_19 = {
    Text = "여기 이 건축가는 내 연구실타래에 있는 모든 파괴 장치를 가지고 있다는 거야."
  },
  AvgDialog_72010_Content_2 = {
    Text = "아니... 아니야."
  },
  AvgDialog_72010_Content_20 = {
    Text = "그리고 나와 동등한 최고 수준의 접근 권한도 가지고 있지."
  },
  AvgDialog_72010_Content_21 = {
    Text = "안 그래?"
  },
  AvgDialog_72010_Content_22 = {
    Text = "복도 끝에서, 다른 한 명과 똑같은 모습의 인물이 천천히 걸어 나온다. 두 사람은 거대한 거울 속의 자신을 보듯, 연구실타래을 가로질러 서로를 응시한다."
